insert into public.pack_prompts (pack_id, prompt_key, category_key, category, category_en, title, title_en, description_pt, description_en, content, content_en, variables_pt, variables_en, is_free_preview, sort_order)
select id, 'tt-hook-curiosity', 'hooks', 'Hooks', 'Hooks', 'Hook de curiosidade', 'Curiosity hook', 'Cria um mistério irresistível', 'Creates an irresistible mystery', 'Cria 5 hooks de 3 segundos para um TikTok sobre {{tema}} que usem a lacuna de curiosidade: revela um resultado surpreendente sem explicar como, para que o espectador fique até ao fim. Máximo 12 palavras por hook.', 'Write 5 three-second TikTok hooks about {{topic}} that use the curiosity gap: reveal a surprising result without explaining how, so the viewer stays to the end. Maximum 12 words per hook.', ARRAY['tema']::text[], ARRAY['topic']::text[], true, 1 from public.prompt_packs where slug = 'tiktok'
