select id, 'tt-structure-pas', 'structure', 'Estrutura', 'Structure', 'Problema, agitação, solução', 'Problem, agitate, solve', 'Estrutura clássica de 30 segundos', 'Classic 30-second framework', 'Cria a estrutura de um TikTok de 30 segundos sobre {{tema}} com tempos indicados: 1. Hook que identifica o problema (3s). 2. Agitação com as consequências (7s). 3. Solução passo a passo (15s). 4. CTA direto (5s). Inclui o texto falado e o texto no ecrã de cada parte.', 'Create the structure of a 30-second TikTok about {{topic}} with timings: 1. Hook naming the problem (3s). 2. Agitate with the consequences (7s). 3. Step-by-step solution (15s). 4. Direct CTA (5s). Include the spoken line and the on-screen text for each part.', ARRAY['tema']::text[], ARRAY['topic']::text[], false, 4 from public.prompt_packs where slug = 'tiktok'
