select id, 'tt-structure-list', 'structure', 'Estrutura', 'Structure', 'Lista progressiva', 'Progressive list', 'Mantém o espectador até ao último ponto', 'Keeps viewers until the last point', 'Cria um TikTok em formato lista sobre {{tema}} com 5 pontos, do menos para o mais surpreendente, guardando o melhor para o fim. Cada ponto tem no máximo 2 frases e um texto de ecrã de até 5 palavras.', 'Create a list-format TikTok about {{topic}} with 5 points, from least to most surprising, saving the best for last. Each point has at most 2 sentences and on-screen text of up to 5 words.', ARRAY['tema']::text[], ARRAY['topic']::text[], false, 5 from public.prompt_packs where slug = 'tiktok'
