select id, 'tt-script-tutorial', 'scripts', 'Guiões', 'Scripts', 'Tutorial rápido de 45 segundos', '45-second quick tutorial', 'Ensina algo útil sem enrolar', 'Teaches something useful, no filler', 'Escreve um guião de 45 segundos que ensine {{tarefa}} a {{publico}}. Começa pelo resultado final, depois mostra 3 passos com ações visuais claras e termina com um erro comum a evitar. Tom: {{tom}}.', 'Write a 45-second script teaching {{task}} to {{audience}}. Open with the end result, then show 3 steps with clear visual actions, and close with a common mistake to avoid. Tone: {{tone}}.', ARRAY['tarefa','publico','tom']::text[], ARRAY['task','audience','tone']::text[], false, 6 from public.prompt_packs where slug = 'tiktok'
