select id, 'yt-ideas', 'planning', 'Planeamento', 'Planning', '20 ideias de vídeos com procura', '20 in-demand video ideas', 'Nunca ficas sem temas', 'Never run out of topics', 'Gera 20 ideias de vídeos para um canal sobre {{nicho}} dirigido a {{publico}}, agrupadas em: pesquisa (como fazer), comparação, opinião e casos reais. Indica para cada uma a pergunta que o público escreve no Google.', 'Generate 20 video ideas for a channel about {{niche}} aimed at {{audience}}, grouped into: search (how-to), comparison, opinion and real cases. For each, give the question the audience types into Google.', ARRAY['nicho','publico']::text[], ARRAY['niche','audience']::text[], false, 7 from public.prompt_packs where slug = 'youtube'
