select id, 'lg-case-summary', 'research', 'Análise', 'Analysis', 'Resumo estratégico de documentos', 'Strategic document summary', 'Transforma documentos longos num briefing', 'Turns long documents into a brief', 'Resume o documento abaixo num briefing com: factos essenciais, partes envolvidas, datas e prazos mencionados, pontos em disputa e questões a confirmar. Não inventes factos nem cites legislação que não esteja no texto. Documento: {{documento}}', 'Summarise the document below into a brief with: key facts, parties involved, dates and deadlines mentioned, disputed points and questions to confirm. Do not invent facts or cite law not in the text. Document: {{document}}', ARRAY['documento']::text[], ARRAY['document']::text[], true, 1 from public.prompt_packs where slug = 'legal'
