select id, 'lg-contract-red-flags', 'contracts', 'Contratos', 'Contracts', 'Pontos de atenção num contrato', 'Contract red flags', 'Primeira leitura rápida', 'A fast first read', 'Lê este contrato de {{tipo_contrato}} e lista as cláusulas que merecem atenção (responsabilidade, rescisão, penalizações, prazos, foro, dados pessoais), explicando porquê em linguagem simples. Indica que é uma triagem inicial para revisão por advogado. Contrato: {{contrato}}', 'Read this {{contract_type}} contract and list the clauses that need attention (liability, termination, penalties, deadlines, jurisdiction, personal data), explaining why in plain language. State that it is an initial screen for a lawyer''s review. Contract: {{contract}}', ARRAY['tipo_contrato','contrato']::text[], ARRAY['contract_type','contract']::text[], false, 4 from public.prompt_packs where slug = 'legal'
