select id, 'lg-client-explain', 'clients', 'Clientes', 'Clients', 'Explicação para o cliente', 'Client-friendly explanation', 'Linguagem clara sem jargão', 'Plain language, no jargon', 'Explica a um cliente sem formação jurídica a situação de {{tema}}: o que está em causa, opções possíveis, riscos de cada uma e próximos passos. Linguagem simples, frases curtas, sem prometer resultados.', 'Explain {{topic}} to a client with no legal background: what is at stake, possible options, risks of each and next steps. Plain language, short sentences, no promises of outcomes.', ARRAY['tema']::text[], ARRAY['topic']::text[], false, 5 from public.prompt_packs where slug = 'legal'
