select id, 'lg-status-email', 'clients', 'Clientes', 'Clients', 'Email de ponto de situação', 'Case status email', 'Mantém o cliente informado', 'Keeps the client informed', 'Escreve um email para {{cliente}} sobre o processo {{referencia}}: ponto de situação atual, o que aconteceu desde o último contacto, próximos marcos com datas previstas e o que precisamos que o cliente envie.', 'Write an email to {{client}} about case {{reference}}: current status, what has happened since the last contact, next milestones with expected dates and what we need the client to send.', ARRAY['cliente','referencia']::text[], ARRAY['client','reference']::text[], false, 6 from public.prompt_packs where slug = 'legal'
