select id, 'lg-intake', 'clients', 'Clientes', 'Clients', 'Questionário de primeira consulta', 'First consultation intake', 'Recolhe a informação certa', 'Collects the right information', 'Cria um questionário de primeira consulta para casos de {{area_direito}}: dados do cliente, descrição dos factos, documentos a trazer, prazos conhecidos e objetivos do cliente.', 'Create a first-consultation intake form for {{practice_area}} cases: client details, description of the facts, documents to bring, known deadlines and the client''s goals.', ARRAY['area_direito']::text[], ARRAY['practice_area']::text[], false, 7 from public.prompt_packs where slug = 'legal'
