select id, 'lg-fee-proposal', 'office', 'Escritório', 'Practice', 'Proposta de honorários', 'Fee proposal', 'Clareza desde o início', 'Clarity from the start', 'Escreve uma proposta de honorários para {{servico}}: âmbito do trabalho, o que não está incluído, modelo de honorários ({{modelo}}), despesas, prazos estimados e condições de pagamento.', 'Write a fee proposal for {{service}}: scope of work, what is not included, fee model ({{model}}), expenses, estimated timelines and payment terms.', ARRAY['servico','modelo']::text[], ARRAY['service','model']::text[], false, 8 from public.prompt_packs where slug = 'legal'
