select id, 'li-profile', 'profile', 'Perfil', 'Profile', 'Título e secção Acerca', 'Headline and About section', 'Perfil que explica o teu valor', 'A profile that explains your value', 'Escreve 5 opções de título de perfil LinkedIn (até 220 caracteres) e uma secção Acerca de 200 palavras para um(a) {{profissao}} que ajuda {{cliente_ideal}} a {{resultado}}. Termina com um CTA para contacto.', 'Write 5 LinkedIn headline options (up to 220 characters) and a 200-word About section for a {{profession}} who helps {{ideal_client}} achieve {{result}}. End with a contact CTA.', ARRAY['profissao','cliente_ideal','resultado']::text[], ARRAY['profession','ideal_client','result']::text[], true, 1 from public.prompt_packs where slug = 'linkedin'
