select id, 'li-post-story', 'posts', 'Publicações', 'Posts', 'Publicação com história e lição', 'Story-and-lesson post', 'O formato com mais alcance', 'The highest-reach format', 'Escreve uma publicação de LinkedIn sobre {{experiencia}}: primeira linha que prenda, história curta, lição aplicável a {{publico}} e uma pergunta final para gerar comentários. Frases curtas, máximo 1300 caracteres, sem hashtags em excesso.', 'Write a LinkedIn post about {{experience}}: a gripping first line, a short story, a lesson applicable to {{audience}} and a closing question to spark comments. Short sentences, max 1300 characters, no hashtag overload.', ARRAY['experiencia','publico']::text[], ARRAY['experience','audience']::text[], true, 2 from public.prompt_packs where slug = 'linkedin'
