select id, 'li-post-expertise', 'posts', 'Publicações', 'Posts', 'Publicação de autoridade', 'Expertise post', 'Mostra conhecimento prático', 'Shows practical know-how', 'Escreve uma publicação de LinkedIn com 5 erros que {{publico}} comete em {{tema}} e como corrigir cada um numa frase. Abre com um dado ou observação concreta da tua experiência.', 'Write a LinkedIn post with 5 mistakes {{audience}} makes with {{topic}} and how to fix each in one sentence. Open with a concrete fact or observation from your experience.', ARRAY['publico','tema']::text[], ARRAY['audience','topic']::text[], false, 3 from public.prompt_packs where slug = 'linkedin'
