select id, 'li-outreach', 'prospecting', 'Prospeção', 'Prospecting', 'Pedido de ligação e mensagem', 'Connection request and message', 'Prospeção sem spam', 'Outreach that is not spam', 'Escreve um pedido de ligação (até 300 caracteres) e uma sequência de 3 mensagens para {{cargo_alvo}} em empresas de {{setor}}. A primeira não vende, a segunda partilha algo útil sobre {{tema}} e a terceira propõe uma conversa de 15 minutos.', 'Write a connection request (up to 300 characters) and a 3-message sequence for {{target_role}} at {{industry}} companies. The first does not sell, the second shares something useful about {{topic}} and the third proposes a 15-minute call.', ARRAY['cargo_alvo','setor','tema']::text[], ARRAY['target_role','industry','topic']::text[], false, 7 from public.prompt_packs where slug = 'linkedin'
