select id, 'hs-social', 'restaurant', 'Restaurante', 'Restaurant', 'Semana de redes sociais', 'A week of social posts', 'Conteúdo sem esforço', 'Effortless content', 'Cria 7 ideias de publicações para Instagram de {{negocio}}: bastidores da cozinha ou da casa, equipa, cliente habitual, prato ou quarto em destaque, evento local, pergunta à comunidade e oferta. Com legenda curta para cada.', 'Create 7 Instagram post ideas for {{business}}: behind the scenes, the team, a regular customer, a featured dish or room, a local event, a community question and an offer. With a short caption for each.', ARRAY['negocio']::text[], ARRAY['business']::text[], false, 7 from public.prompt_packs where slug = 'hospitality'
