select id, 'hs-complaint', 'reviews', 'Avaliações', 'Reviews', 'Resposta a reclamação', 'Complaint reply', 'Resolve antes de virar avaliação', 'Resolve it before it becomes a review', 'Escreve uma resposta privada a esta reclamação de um cliente: "{{reclamacao}}". Pede desculpa sem desculpas vagas, propõe uma solução concreta ({{solucao}}) e confirma o próximo passo.', 'Write a private reply to this customer complaint: "{{complaint}}". Apologise without vague excuses, offer a concrete solution ({{solution}}) and confirm the next step.', ARRAY['reclamacao','solucao']::text[], ARRAY['complaint','solution']::text[], false, 8 from public.prompt_packs where slug = 'hospitality'
