select id, 'em-subjects', 'subjects', 'Assuntos', 'Subject lines', '20 assuntos para testar', '20 subject lines to test', 'Mais aberturas', 'More opens', 'Escreve 20 linhas de assunto para um email sobre {{tema}} para {{publico}}, até 45 caracteres, em 5 estilos: curiosidade, benefício, pergunta, número e urgência honesta. Junta uma pré-visualização para as 5 melhores.', 'Write 20 subject lines for an email about {{topic}} for {{audience}}, up to 45 characters, in 5 styles: curiosity, benefit, question, number and honest urgency. Add preview text for the best 5.', ARRAY['tema','publico']::text[], ARRAY['topic','audience']::text[], true, 2 from public.prompt_packs where slug = 'email-marketing'
