select id, 'em-promo', 'campaigns', 'Campanhas', 'Campaigns', 'Email de promoção', 'Promotional email', 'Oferta clara, um só CTA', 'Clear offer, one CTA', 'Escreve um email de promoção para {{oferta}} válida até {{data_fim}}: assunto, abertura com o benefício, detalhes da oferta, para quem é, prova social e CTA. Inclui uma versão curta para o lembrete do último dia.', 'Write a promotional email for {{offer}} valid until {{end_date}}: subject, an opening with the benefit, offer details, who it is for, social proof and CTA. Include a short version for the last-day reminder.', ARRAY['oferta','data_fim']::text[], ARRAY['offer','end_date']::text[], false, 4 from public.prompt_packs where slug = 'email-marketing'
