select id, 'em-winback', 'sequences', 'Sequências', 'Sequences', 'Reativar subscritores inativos', 'Win back inactive subscribers', 'Limpa a lista e recupera clientes', 'Cleans the list and recovers customers', 'Cria uma sequência de 3 emails para subscritores de {{negocio}} sem abrir emails há 90 dias: "sentimos a tua falta" com o melhor conteúdo, incentivo de {{incentivo}} e último email a perguntar se querem continuar na lista.', 'Create a 3-email sequence for {{business}} subscribers who have not opened in 90 days: "we miss you" with the best content, an incentive of {{incentive}} and a final email asking if they want to stay on the list.', ARRAY['negocio','incentivo']::text[], ARRAY['business','incentive']::text[], false, 5 from public.prompt_packs where slug = 'email-marketing'
