select id, 'cs-angry', 'replies', 'Respostas', 'Replies', 'Cliente irritado', 'Angry customer', 'Acalma e resolve', 'Calms and resolves', 'Escreve uma resposta a este cliente irritado: "{{mensagem}}". Reconhece a frustração, assume o que for da nossa responsabilidade, apresenta a solução {{solucao}} com prazo e evita frases feitas.', 'Write a reply to this angry customer: "{{message}}". Acknowledge the frustration, own what is ours, present the solution {{solution}} with a timeframe and avoid stock phrases.', ARRAY['mensagem','solucao']::text[], ARRAY['message','solution']::text[], true, 2 from public.prompt_packs where slug = 'customer-support'
