select id, 'fl-proposal', 'proposals', 'Propostas', 'Proposals', 'Proposta comercial completa', 'Complete client proposal', 'Estrutura que fecha negócios', 'A structure that wins work', 'Escreve uma proposta para {{cliente}} sobre {{projeto}}: resumo do problema, objetivo, abordagem em fases, entregáveis, prazos, investimento com 3 opções de pacote, o que não está incluído e próximos passos.', 'Write a proposal for {{client}} about {{project}}: problem summary, goal, phased approach, deliverables, timelines, investment with 3 package options, what is not included and next steps.', ARRAY['cliente','projeto']::text[], ARRAY['client','project']::text[], true, 1 from public.prompt_packs where slug = 'freelancers'
