select id, 'fl-pricing', 'pricing', 'Preços', 'Pricing', 'Defender o preço', 'Defending your price', 'Responde a "está caro"', 'Answering "it''s too expensive"', 'O cliente disse "{{objecao}}" sobre o orçamento de {{valor}} para {{servico}}. Escreve uma resposta que reforce o valor, ofereça reduzir o âmbito em vez do preço e proponha um próximo passo.', 'The client said "{{objection}}" about the {{amount}} quote for {{service}}. Write a reply that reinforces the value, offers to reduce scope instead of price and proposes a next step.', ARRAY['objecao','valor','servico']::text[], ARRAY['objection','amount','service']::text[], false, 3 from public.prompt_packs where slug = 'freelancers'
