select id, 'fl-payment-reminder', 'admin', 'Gestão', 'Admin', 'Lembretes de pagamento', 'Payment reminders', 'Firmes mas educados', 'Firm but polite', 'Escreve 3 lembretes de pagamento para a fatura {{numero_fatura}} de {{valor}} vencida a {{data}}: lembrete simpático, segundo lembrete firme com nova data e aviso final com as consequências previstas no contrato.', 'Write 3 payment reminders for invoice {{invoice_number}} of {{amount}} due on {{date}}: a friendly reminder, a firm second reminder with a new date and a final notice with the consequences set out in the contract.', ARRAY['numero_fatura','valor','data']::text[], ARRAY['invoice_number','amount','date']::text[], false, 5 from public.prompt_packs where slug = 'freelancers'
