select id, 'fl-scope-creep', 'admin', 'Gestão', 'Admin', 'Pedido fora do âmbito', 'Out-of-scope request', 'Diz que sim, com orçamento', 'Say yes, with a quote', 'O cliente pediu "{{pedido}}", que não está na proposta. Escreve uma resposta positiva que reconheça o pedido, explique que está fora do âmbito e apresente duas opções: orçamento adicional ou trocar por outro entregável.', 'The client asked for "{{request}}", which is not in the proposal. Write a positive reply that acknowledges the request, explains it is out of scope and offers two options: an extra quote or swapping another deliverable.', ARRAY['pedido']::text[], ARRAY['request']::text[], false, 6 from public.prompt_packs where slug = 'freelancers'
