select id, 'fl-testimonial', 'growth', 'Crescer', 'Growth', 'Pedido de testemunho e indicação', 'Testimonial and referral request', 'Clientes que trazem clientes', 'Clients who bring clients', 'Escreve uma mensagem para {{cliente}} no fim do projeto {{projeto}} a pedir um testemunho com 3 perguntas guia e, na mesma mensagem, se conhece alguém que possa beneficiar do mesmo serviço.', 'Write a message to {{client}} at the end of project {{project}} asking for a testimonial with 3 guiding questions and, in the same message, whether they know anyone who could benefit from the same service.', ARRAY['cliente','projeto']::text[], ARRAY['client','project']::text[], false, 8 from public.prompt_packs where slug = 'freelancers'
