select id, 'pm-excel', 'spreadsheets', 'Folhas de cálculo', 'Spreadsheets', 'Fórmula de Excel ou Google Sheets', 'Excel or Google Sheets formula', 'Explicada passo a passo', 'Explained step by step', 'Preciso de uma fórmula de {{ferramenta}} que {{objetivo}}. Os dados estão nas colunas {{colunas}}. Dá a fórmula, explica cada parte e sugere uma alternativa mais simples se existir. Usa ponto e vírgula como separador de argumentos.', 'I need a {{tool}} formula that {{goal}}. The data is in columns {{columns}}. Give the formula, explain each part and suggest a simpler alternative if there is one.', ARRAY['ferramenta','objetivo','colunas']::text[], ARRAY['tool','goal','columns']::text[], true, 2 from public.prompt_packs where slug = 'sme-productivity'
