select id, 'pm-sop', 'processes', 'Processos', 'Processes', 'Procedimento operacional', 'Standard operating procedure', 'Tarefas feitas sempre da mesma forma', 'Tasks done the same way every time', 'Escreve um procedimento para {{tarefa}} em {{negocio}}: objetivo, responsável, quando se faz, materiais necessários, passos numerados, erros comuns e como verificar que ficou bem feito.', 'Write a procedure for {{task}} at {{business}}: purpose, owner, when it is done, materials needed, numbered steps, common mistakes and how to check it was done right.', ARRAY['tarefa','negocio']::text[], ARRAY['task','business']::text[], false, 3 from public.prompt_packs where slug = 'sme-productivity'
