select id, 'pm-report', 'reports', 'Relatórios', 'Reports', 'Relatório mensal para a gestão', 'Monthly management report', 'Números com contexto', 'Numbers with context', 'Com estes dados do mês: {{dados}}, escreve um relatório de uma página para a gestão de {{negocio}}: resumo em 3 frases, indicadores principais face ao mês anterior, o que correu bem, o que correu mal e 3 ações para o próximo mês.', 'Using this month''s data: {{data}}, write a one-page management report for {{business}}: a 3-sentence summary, key indicators versus last month, what went well, what went badly and 3 actions for next month.', ARRAY['dados','negocio']::text[], ARRAY['data','business']::text[], false, 5 from public.prompt_packs where slug = 'sme-productivity'
